const LESSONS = [L1, L2, L3, L4, L5, L6]
// ─── Дополнения по аудиту полноты: серии кадров, текстовые эквиваленты, разборы ──────────
type Par = ReturnType<typeof p>
const LK = (k: string): AccLesson => (LESSONS as AccLesson[]).find(l => l.key === k) as AccLesson
const ins = (k: string, after: string, ...ps: Par[]) => {
  const arr = LK(k).content.paragraphs
  const i = arr.findIndex(x => x.id === after)
  if (i < 0) throw new Error(`ins: нет абзаца ${after} в ${k}`)
  arr.splice(i + 1, 0, ...ps)
}
const addFigs = (k: string, f: Array<{ after: string; caption: string; src: string }>) => {
  const F = FIGS as unknown as Record<string, unknown[]>
  F[k] = [...(F[k] ?? []), ...f]
}
const cap = (n: number, m: number, t: string) => `Учебная реконструкция: шаг ${n} из ${m} — ${t}.`
const XLA = 'Excel для Windows (Microsoft 365)'
/** Лист Excel с произвольными буквами столбцов и номерами строк. */
const grid = (cols: string[], rows: string[][], first = 1, hi?: [number, number]) => ({ headers: ['', ...cols], rows: rows.map((r, i) => [String(first + i), ...r]), hi })

// m05-01: рецепт «моста» формулами
ins('m05-01', 'bridge', p('bridge2', '**«Мост» формулами (на листе «Сверка» практикума, после уроков 02 и 03).** Здесь C — сумма банка по ID реестра или текст «Нет в банке», D — разница, G — отметка «Нет в реестре». Каждая причина — одна формула:\n— Нет в банке: `=СУММЕСЛИ(C2:C5;"Нет в банке";B2:B5)` → 4 000. Банк меньше на эту сумму, вклад −4 000.\n— Разные суммы: `=СУММ(D2:D5)` → 100 (текст «Проверить» в D3 функция пропускает). Банк меньше на 100, вклад −100.\n— Нет в реестре: `=СУММЕСЛИ(G2:G5;"Нет в реестре";F2:F5)` → 500. Банк больше на 500, вклад +500.\nИтого: `=-4000-100+500` = −3 600 — ровно разница из контрольных сумм. Если мост не сходится, в данных есть причина, которую вы не назвали.'))
ins('m05-01', 'bridge2', p('bridgeT', '**Таблица «причина → вклад» текстом:**\n— P02, суммы разные (8 000 против 7 900) — вклад −100\n— P03, нет в банке (4 000 в реестре) — вклад −4 000\n— P99, нет в реестре (500 в банке) — вклад +500\n— Итого — −3 600; разница банк − реестр: 29 400 − 33 000 = −3 600; остаток 0'))

// m05-02: дубль ID в учебных данных, формула по частям
ins('m05-02', 'expected', p('dup2', '**Как воспроизвести «Дубль ID» (в учебных данных его нет).** В E6 введите `P01`, в F6 — `12000`, затем растяните диапазоны в формуле C2 с `$E$2:$E$5` на `$E$2:$E$6` (и `$E$2:$F$5` на `$E$2:$F$6`). Теперь для P01 `СЧЁТЕСЛИ` даёт 2, в C2 — «Дубль ID», в D2 — «Проверить». Это нужно, чтобы увидеть ветку формулы; строку E6:F6 затем удалите.'),
  p('parts2', '**Длинная формула шага 1 по частям.** Вынесите счётчик во вспомогательный столбец K: `K2: =СЧЁТЕСЛИ($E$2:$E$5;A2)` — сколько раз ID реестра есть в банке (P01 — 1, P02 — 1, P03 — 0, P04 — 1). Тогда C2 читается легко:\n`=ЕСЛИ(K2=0;"Нет в банке";ЕСЛИ(K2>1;"Дубль ID";ВПР(A2;$E$2:$F$5;2;ЛОЖЬ)))`\nАнгл.: `=IF(K2=0,"Нет в банке",IF(K2>1,"Дубль ID",VLOOKUP(A2,$E$2:$F$5,2,FALSE)))`\nТри ветки: нет — «Нет в банке»; больше одного — «Дубль ID»; ровно один — сумма из банка. Результат тот же, формула вдвое короче.'))

// m05-03: построить «Повторную оплату» и отличить частичную
ins('m05-03', 'expected', p('build3', '**Как построить статус повторной оплаты самому (лист «Сверка»).** В L1 напишите «Статус банка» (столбцы H:I заняты итогами урока 01, K — вспомогательным столбцом урока 02). В L2:\n`=ЕСЛИ(СЧЁТЕСЛИ($E$2:E2;E2)>1;"Повторная оплата";ЕСЛИ(СЧЁТЕСЛИ($A$2:$A$5;E2)=0;"Нет в реестре";"Есть"))`\nАнгл.: `=IF(COUNTIF($E$2:E2,E2)>1,"Повторная оплата",IF(COUNTIF($A$2:$A$5,E2)=0,"Нет в реестре","Есть"))`\nПорядок важен: сначала повтор (растущий диапазон), потом «нет в реестре». Протяните до L5. Чтобы увидеть повтор, в E6 введите `P04`, в F6 — `9000`, добавьте L6 протягиванием — вернётся «Повторная оплата».'),
  p('part3', '**Частичная оплата и повтор — разные вещи.** Пример (вымышленный): в реестре P05 — 9 000; в банке две строки P05: 5 000 (10.11) и 4 000 (12.11). Сумма по ID `=СУММЕСЛИ($E$2:$E$7;"P05";$F$2:$F$7)` = 9 000 = реестру — это частичная оплата, а не повтор, и ничего возвращать не нужно. Для P106 из шаблона обе строки по 2 500, реестр — 2 500: сумма по ID 5 000 больше реестра на 2 500 — это повторная оплата. Признак различия: сошлась ли сумма по всем строкам ID с реестром. Одинаковые суммы и даты рядом — повод проверить, но не доказательство.'))

// m05-04: разбор статуса по строкам, неоднозначность, серия кадров условного форматирования
ins('m05-04', 'order', p('byrow4', '**Как формула статуса читает строки шаблона (текстом).**\n— P101: в банке 1 строка с этим ID, сумма 10 000 = реестру → «Совпало».\n— P104: ID в банке нет (E=0), по дата+сумма+контрагент — 0 строк → «Нет в банке».\n— P105: в банке ID пуст, E=0, но по дата+сумма+контрагент 1 строка → «Найдено по дата+сумма+контрагент».\n— P106: в банке две строки с P106 (E=2) → «Повтор оплаты в банке».\n— P107: в банке 1 строка, но 7 020 вместо 7 200 → «Расхождение суммы».'),
  p('amb4', '**Одинаковая сумма у двух контрагентов или двух строк.** Столбец H считает строки банка по трём признакам сразу (дата, сумма, контрагент), поэтому «чужой» платёж на ту же сумму его не обманет: контрагент другой. Но если в банке две строки с одной датой, суммой и контрагентом, `H2` станет 2, и платёж нельзя привязать однозначно. Измените ветку: `ЕСЛИ(H2=1;"Найдено по дата+сумма+контрагент";ЕСЛИ(H2>1;"Неоднозначно: проверить вручную";"Нет в банке"))`. Неоднозначную строку не закрывайте автоматически: сверьте с назначением платежа и впишите ID в выписку.'))
